// Módulo gerado pelo plugin vite-blog-index.ts: metadados dos artigos, sem o texto completo.
declare module "virtual:blog-index" {
  const entries: {
    slug: string;
    locale: "pt" | "en" | "es";
    data: Record<string, string | string[]>;
    words: number;
    headings: { id: string; text: string; level: 2 | 3 }[];
  }[];
  export default entries;
}
